  const simple = (n) => [SEC('Your details', 'So we know who you are', [Q('short', 'Full Name', { ph: 'First and last name' }), Q('date', 'Date of Birth')]), SEC(n, '', [Q('long', 'Tell us more', { ph: 'Type your answer', req: false }), Q('radio', 'Have you completed this before?', { opts: ['Yes', 'No'] })])];
