  chs['ct-cat'] = el => { el.checked ? tf.cats.add(el.dataset.v) : tf.cats.delete(el.dataset.v); keep(); }; chs['ct-all'] = () => { tf.cats.clear(); keep(); };
  acts['ct-more'] = el => { tf.more[el.dataset.v] = !tf.more[el.dataset.v]; keep(); }; acts['ct-coll'] = el => { tf.coll[el.dataset.v] = !tf.coll[el.dataset.v]; keep(); };
